              <input
                type="number"
                value={addingPartToModel.stock}
                onChange={e => setAddingPartToModel(prev => ({ ...prev, stock: e.target.value }))}
                className="w-full p-2.5 rounded-xl border border-slate-300 font-extrabold"
              />
